-- Reverse of apply.sql: disable the crawled source (kept, with its articles) and re-enable the old RSS feed. Generated by Build-Sql.py.
\set ON_ERROR_STOP on
SET lock_timeout = '5s';
BEGIN;
DO $do$ DECLARE k int; BEGIN
  UPDATE feeds SET enabled = false WHERE publisher_id = 1560 AND feed_url = 'https://www.hoy.com.py/' AND feed_type = 'html' AND enabled;
  GET DIAGNOSTICS k = ROW_COUNT; IF k <> 1 THEN RAISE EXCEPTION 'crawled source: % rows, expected 1', k; END IF;
  UPDATE feeds SET enabled = true WHERE publisher_id = 1560 AND feed_url = 'https://www.hoy.com.py/rss' AND NOT enabled;
  GET DIAGNOSTICS k = ROW_COUNT; IF k <> 1 THEN RAISE EXCEPTION 'old RSS feed: % rows, expected 1', k; END IF;
END $do$;
COMMIT;
